/**
 * MediaWiki style sheet for general styles on basic content elements.
 * IMPORTANT: All rules in this file should only apply to __tag__ selectors (T255717).
 * Styling of non-tag selectors is permitted for backwards compatibility, in only two cases:
 * 1) There is an equivalent tag with the same name in HTML4 (e.g. `.small and <small>)
 * 2) A class matches a tag name and is prefixed with `mw-` e.g. `code` and `.mw-code`
 *
 * Styles for basic elements: links, headings, lists, ….
 *
 * This style sheet is used by the Monobook and Vector skins.
 */

@import 'mediawiki.mixins.less';
@import 'mediawiki.skin.variables.less';

/* stylelint-disable selector-class-pattern */

/* Links */
a {
	text-decoration: none;
	color: @color-link;
	background: none;

	&:not( [ href ] ) {
		cursor: pointer; /* Always cursor:pointer even without href */
	}

	&:visited {
		color: @color-link--visited;
	}

	&:active {
		color: @color-link--active;
	}

	&:hover,
	&:focus {
		text-decoration: underline;
	}
}

/* Inline Elements */
img {
	border: 0; /* FIXME: Remove after adding 'normalize.less' added to all 'elements.less' calling skins. */
	vertical-align: middle;
}

hr {
	// Use `@border-width-base` instead of `1px` to match the default border width.
	height: @border-width-base;
	// Use `@border-color-base` as the element represents a border.
	background-color: @border-color-base;
	border: 0;
	margin: 0.2em 0;
}

/* Structural Elements */
.mw-heading,
h1,
h2,
h3,
h4,
h5,
h6 {
	color: @color-emphasized;
	font-weight: bold;
	margin: 0;
	padding-top: 0.5em;
	padding-bottom: 0.17em;
	// Create a "block formatting context" so that the bottom border on headings
	// don't overlap floated content like infoboxes or thumbnails.
	// In addition, word-break:break-word forces heading to span multiple lines.
	// Together, these two rules are a substitute for overflow: hidden.
	// https://developer.mozilla.org/en-US/docs/Web/CSS/display#flow-root
	/* stylelint-disable-next-line plugin/no-unsupported-browser-features */
	display: flow-root;
	/* stylelint-disable-next-line declaration-property-value-keyword-no-deprecated */
	word-break: break-word;
}

.mw-heading1,
h1,
.mw-heading2,
h2 {
	margin-bottom: 0.6em;
	border-bottom: @border-width-base @border-style-base @border-color-base;
}

.mw-heading3,
h3,
.mw-heading4,
h4,
.mw-heading5,
h5 {
	margin-bottom: 0.3em;
}

.mw-heading1,
h1 {
	font-size: 188%;
	font-weight: normal;
}

.mw-heading2,
h2 {
	font-size: 150%;
	font-weight: normal;
}

.mw-heading3,
h3 {
	font-size: 128%;
}

.mw-heading4,
h4 {
	font-size: 116%;
}

.mw-heading5,
h5 {
	font-size: 108%;
}

.mw-heading6,
h6 {
	font-size: 100%;
}

// Override all styles above for `hN` nested inside `.mw-heading`, as used on wikitext pages.
// Also override the most common skin-defined styles to make the migration after T13555 easier.
.mw-heading {
	h1,
	h2,
	h3,
	h4,
	h5,
	h6 {
		// Must be inline to allow `.mw-editsection` to be shown on the same line
		display: inline;
		border: 0;
		margin: 0;
		padding: 0;
		color: inherit;
		font: inherit;
	}
}

p {
	margin: 0.4em 0 0.5em 0;

	img {
		margin: 0;
	}
}

ul {
	margin-top: 0.3em;
	margin-bottom: 0;
	.margin-inline( 1.6em, 0 );
	padding: 0;
}

ol {
	margin-top: 0.3em;
	margin-bottom: 0;
	.margin-inline( 3.2em, 0 );
	padding: 0;
	list-style-image: none;
}

dd {
	margin-bottom: 0.1em;
	.margin-inline( 1.6em, 0 );
}

li {
	margin-bottom: 0.1em;
}

dt {
	font-weight: bold;
	margin-bottom: 0.1em;
}

dl {
	margin-top: 0.2em;
	margin-bottom: 0.5em;
}

/* FIXME: Duplicated ruleset if skins using ResourceLoaderSkinModule
load the features `normalize` and `elements`. */
pre,
code,
tt,
kbd,
samp,
.mw-code {
	/* Support: Blink, Gecko, Webkit; enable unified font sizes for monospace font. T176636 */
	font-family: monospace, monospace;
}

pre,
code,
.mw-code {
	background-color: @background-color-neutral-subtle;
	color: @color-emphasized;
	border: @border-width-base @border-style-base @border-color-muted;
}

code {
	border-radius: @border-radius-base;
	padding: 1px 4px;
}

pre,
.mw-code {
	padding: 1em;
	/* Wrap lines in overflow. T2260, T103780 */
	white-space: pre-wrap;
	/* Create a new block formatting context */
	overflow-x: hidden;
	/* Break really long words when they overflow to the next line */
	overflow-wrap: break-word;
}

/* Tables */
table {
	font-size: 100%;
}

/* Forms */
fieldset {
	border: @border-width-base @border-style-base #2a4b8d;
	margin: 1em 0 1em 0;
	padding: 0 1em 1em;
}

legend {
	padding: 0.5em;
}

form {
	border: 0;
	margin: 0;
}

textarea {
	display: block;
	box-sizing: @box-sizing-base;
	width: 100%;
	/* Support: Firefox */
	/* Border rule required to override system appearance on Linux. T13641. */
	border: @border-width-base @border-style-base @border-color-base;
	padding: 0.1em;
}

/* Emulate Center */
.center {
	width: 100%;
	text-align: center;
}

*.center * {
	margin-left: auto;
	margin-right: auto;
}

/* Small for tables and similar */
.small {
	font-size: 94%;

	table& {
		font-size: 100%;
	}
}

// Common LESS mixin library for MediaWiki
//
// By default the folder containing this file is included in the LESS import paths,
// which makes this file importable by all less files via `@import 'mediawiki.mixins.less';`.
//
// The mixins included below are considered a public interface for MediaWiki extensions.
// The signatures of parameterized mixins should be kept as stable as possible.
//
// See <http://lesscss.org/#-mixins> for more information about how to write mixins.

/* stylelint-disable selector-class-pattern */

.hyphens( @value: auto ) {
	& when ( @value = auto ) {
		// Support (`break-word`/`normal`): Firefox 49+, Chrome 23+, Edge 18+, Safari 6.1+, iOS 7+,
		// Android 4.4+, Opera 12.1+
		overflow-wrap: break-word;
	}
	& when ( @value = none ) {
		overflow-wrap: normal;
	}

	// CSS3 hyphenation
	// Chrome < 55 support "-webkit-hyphens: none",
	// but not the "auto" property. It is advisable to set the @lang attribute
	// on the HTML element to enable hyphenation support and improve accessibility.
	// Chrome 55-87 only supports `auto` exclusively on Mac platform.
	/* stylelint-disable plugin/no-unsupported-browser-features */
	-webkit-hyphens: @value; // Safari 5.1+, iOS 4.2+
	hyphens: @value;         // Firefox 43+, Chrome 55+, Safari 17+, iOS 17+, Android 62+, UC Browser 11.8+, Samsung 6.2+
	/* stylelint-enable plugin/no-unsupported-browser-features */
}

// Use to truncate overflow text with value of `ellipsis` (mixin default)
// a custom string (Firefox 9+ only).
// Recommended usage: `text-overflow( @visible: false )` for best readability.
.text-overflow( @visible: false, @value: ellipsis ) {
	& when ( @visible = true ) {
		overflow: visible;
		text-overflow: clip;
		white-space: normal;
	}
	& when ( @visible = false ) {
		overflow: hidden;
		text-overflow: @value;
		white-space: nowrap;
	}
}

// Enable (`text` or `element`) or prevent (`none`) text/element selection.
// Since MW 1.38
.user-select( @value ) {
	-webkit-user-select: @value; // Chrome 4-53, Safari 3.1-, Opera 15-40
	-moz-user-select: @value; // Firefox 2-68
	user-select: @value;
}

// In the future this can be simply migrated to `margin-block: @start @end;`
// Since MW 1.44
.margin-block( @start, @end ) {
	margin-top: @start;
	margin-bottom: @end;
	/* stylelint-disable declaration-block-no-redundant-longhand-properties */
	margin-block-start: @start; // Firefox 41, Safari 12.1, Chrome 69, Opera 56
	margin-block-end: @end;
	/* stylelint-enable declaration-block-no-redundant-longhand-properties */
}

// In the future this can be simply migrated to `margin-inline: @start @end;`
// Since MW 1.43
.margin-inline( @start, @end ) {
	margin-left: @start;
	margin-right: @end;
	/* stylelint-disable declaration-block-no-redundant-longhand-properties */
	margin-inline-start: @start; // Firefox 41, Safari 12.1, Chrome 69, Opera 56
	margin-inline-end: @end;
	/* stylelint-enable declaration-block-no-redundant-longhand-properties */
}

// In the future this can be simply migrated to `padding-block: @start @end;`
// Since MW 1.44
.padding-block( @start, @end ) {
	padding-top: @start;
	padding-bottom: @end;
	/* stylelint-disable declaration-block-no-redundant-longhand-properties */
	padding-block-start: @start; // Firefox 41, Safari 12.1, Chrome 69, Opera 56
	padding-block-end: @end;
	/* stylelint-enable declaration-block-no-redundant-longhand-properties */
}

// In the future this can be simply migrated to `padding-inline: @start @end;`
// Since MW 1.43
.padding-inline( @start, @end ) {
	padding-left: @start;
	padding-right: @end;
	/* stylelint-disable declaration-block-no-redundant-longhand-properties */
	padding-inline-start: @start; // Firefox 41, Safari 12.1, Chrome 69, Opera 56
	padding-inline-end: @end;
	/* stylelint-enable declaration-block-no-redundant-longhand-properties */
}

// Not supported in Chrome <= 55, Firefox <= 31, Opera <= 41
.position-sticky() {
	-webkit-position: sticky; // Support: Safari < 13
	/* stylelint-disable-next-line plugin/no-unsupported-browser-features */
	position: sticky;
}

.column-count( @value ) {
	-moz-column-count: @value; // Firefox 2-51
	column-count: @value; // Chrome 50+, Firefox 52+, Edge, Opera 11.5+, Android 90+
}

.column-width( @value ) {
	-moz-column-width: @value; // Firefox 1.5-49
	column-width: @value; // Chrome 50+, Firefox 50+, Edge, Opera 11.5+, Safari 9+
}

.column-break-inside-avoid() {
	page-break-inside: avoid; // Firefox 1.5-91
	break-inside: avoid-column; // Chrome 80+, Firefox 92+, Edge 80+, Safari 13.1+, Opera 67+
}

.flex-display( @display: flex ) {
	display: @display;
}

.flex-wrap( @wrap: wrap ) {
	flex-wrap: @wrap;
}

.flex( @grow: 1, @shrink: 1, @width: auto, @order: 1 ) {
	// Current spec
	justify-content: space-between;
	width: @width; // Fallback for flex-basis
	flex: @grow @shrink @width;
	order: @order;
}

// “Clearfix Reloaded” Mixin
// The mixin is used on a container with floating children.
// Margin collapsing is a feature, not a bug, hence relying on `display: block` as default.
// With `.mixin-clearfix( @collapse: false; );` you call it to let `margin`s not collapse.
// See https://www.cssmojo.com/the-very-latest-clearfix-reloaded/
// In future we might replace the `&:after` pseudo-element with
// `display: flow-root;` altogether.
// Support: Firefox 3.5+, Safari 4+, Chrome, Opera 15+
.mixin-clearfix( @collapse: true ) {
	&::after {
		clear: both;

		// Margin collapsing as feature. Apply it.
		& when ( @collapse ) {
			content: '';
			display: block;
		}
	}
	// Margin collapsing as bug. Prevent it.
	& when not ( @collapse ) {
		&::before,
		&::after {
			content: '';
			display: table;
		}
	}
}

/* stylelint-disable selector-no-vendor-prefix */
.mixin-placeholder( @rules ) {
	// Chrome 4-56, WebKit, Blink, Edge 12-18
	&::-webkit-input-placeholder {
		@rules();
	}
	// W3C Standard Selectors Level 4
	&::placeholder {
		@rules();
	}
}
/* stylelint-enable selector-no-vendor-prefix */

// Screen Reader Helper Mixin
.mixin-screen-reader-text() {
	display: block;
	position: absolute !important; /* stylelint-disable-line declaration-no-important */
	clip: rect( 1px, 1px, 1px, 1px );
	width: 1px;
	height: 1px;
	margin: -1px;
	border: 0;
	padding: 0;
	overflow: hidden;
}

.solid-to-opacity( @color, @opacity, @background: #fff ) {
	@result: fade( ( ( @color - ( 1 - @opacity ) * ( @background ) ) / @opacity ), @opacity * 100 );
}

/**
 * Compute the most transparent color that appears the same as @color
 * when overlaid on the given @background.
 *
 * @example
 *   background-color: .solid-to-minimum-opacity( #eaecf0 )[ @result ];
 *
 * @param {Color} @color The solid color to approximate with transparency
 * @param {Color} [@background=white] The background color to overlay on
 * @return {Color} @result
 */
.solid-to-minimum-opacity( @color, @background: #fff ) {
	@opacity: 1 - ( min( red( @color ), green( @color ), blue( @color ) ) / 255 );
	@result: .solid-to-opacity( @color, @opacity, @background )[ @result ];
}

// Generate selectors for custom dark mode styles.
// Use design tokens instead of this mixin if possible.
// See https://doc.wikimedia.org/codex/latest/design-tokens/color.html
.darkmode-override( @rules ) {
	@media screen {
		html.skin-theme-clientpref-night & {
			@rules();
		}
	}

	/* stylelint-disable-next-line plugin/no-unsupported-browser-features */
	@media screen and ( prefers-color-scheme: dark ) {
		html.skin-theme-clientpref-os & {
			@rules();
		}
	}
}

// This file is used as a fallback match for "mediawiki.skin.variables.less"
// in the LESS import directories for skins that do not define
// this file themselves.

@import 'mediawiki.skin.defaults.less';

// This file is the central place where we declare
// which variables are part of the "mediawiki.skin.variables.less"
// API that core and extensions can use in their style modules.
// This includes all of the Codex design tokens, as well as some additional variables.
//
// The initial values are intended merely as fallback to allow
// forward and backward compatibility to allow new variables
// to be defined without breaking existing implementations by
// skins.
//
// @since 1.36
// Add `@since` line above every added variable (block) per MediaWiki version.
//
// == Instructions for skins ==
//
// In skin.json, add:
//    "SkinLessImportPaths": {
//        "skinname": "resources/mediawiki.less"
//    }
//
// Create a file called resources/mediawiki.less/mediawiki.skin.variables.less, which starts with:
//    @import 'mediawiki.skin.default.less';
// then import the Codex theme for this skin, e.g.:
//    @import 'mediawiki.skin.codex-design-tokens/theme-wikimedia-ui.less';
// followed by any overrides for these variables, e.g.:
//    @min-width-breakpoint-desktop: 1234px;

// Make all Codex mixins available when mediawiki.skin.variables.less is imported
@import 'mediawiki.skin.codex/mixins/codex-public-mixins.less';

// Skin variables that are not Codex tokens:

// Form input labels for buttons, dropdowns, but also text input values.
// Note that there are binary inputs in skins like Vector, that receive a different treatment
// with name `*-input-binary`.
@line-height-label: 1.6;

// Colors
@color-link: #0645ad;
@color-link--visited: #0b0080;
@color-link--active: #faa700;
// Link colors for new or missing articles, also known as “Red links”.
// https://www.wikidata.org/wiki/Q13417974#sitelinks-wikipedia
@color-link-new: @color-link-red;
@color-link-new--visited: @color-link-red--visited;
@color-link-external: #36b;
@color-link-external--visited: #636; // See T5112.
@color-link-external--active: #b63;

// ----- Neutral values for Codex tokens: -----
// @since 1.41
// We don't import any of the existing Codex themes here. Instead, we provide neutral, unbranded
// values for every Codex token. Skins can override these individually, or they can override them
// en masse by importing a Codex theme. In the future, these values should be migrated into
// Codex as its base theme, once Codex has a proper theming system that allows for this (T296689).

@font-size-base: 1em;
// Please note, that in Codex `font-size` and `line-height` are featuring CSS custom properties
// since v2.0.0-rc.1 in order to support font modes in skins.
@font-size-x-small: 0.75rem; // `x` stands for extra. In this case extra small.
@font-size-small: 0.875rem;
@font-size-medium: 1rem;
@font-size-large: 1.125rem;
@font-size-x-large: 1.25rem;
@font-size-xx-large: 1.5rem;
@font-size-xxx-large: 1.75rem;
@accent-color-base: #0645ad;
@background-color-base: #fff;
@background-color-base-fixed: #fff;
@background-color-content-added: #afb6e9;
@background-color-content-removed: #fc3;
@background-color-interactive: #eee;
@background-color-interactive--hover: #dadde3;
@background-color-interactive--active: #c8ccd1;
@background-color-interactive-subtle: #f9f9f9;
@background-color-interactive-subtle--hover: #eaecf0;
@background-color-interactive-subtle--active: #dadde3;
@background-color-inverted: #000;
@background-color-disabled: #ccc;
@background-color-disabled-subtle: #eee;
@background-color-progressive: #0645ad;
@background-color-progressive--hover: #447ff5;
@background-color-progressive--active: #2a4b8d;
@background-color-progressive--focus: #0645ad;
@background-color-progressive-subtle: #eaf3ff;
@background-color-progressive-subtle--hover: #dce3f9;
@background-color-progressive-subtle--active: #cbd6f6;
@background-color-destructive: #d03;
@background-color-destructive--hover: #ff4242;
@background-color-destructive--active: #b32424;
@background-color-destructive--focus: #d03;
@background-color-destructive-subtle: #fee7e6;
@background-color-destructive-subtle--hover: #ffdad3;
@background-color-destructive-subtle--active: #ffc8bd;
@background-color-error: #d73333;
@background-color-error--hover: #ff4242;
@background-color-error--active: #b32424;
@background-color-error-subtle: #fee7e6;
@background-color-error-subtle--hover: #ffdad3;
@background-color-error-subtle--active: #ffc8bd;
@background-color-warning-subtle: #fef6e7;
@background-color-success-subtle: #d5fdf4;
@background-color-notice-subtle: #eee;
@background-color-backdrop-light: rgba( 255, 255, 255, 0.65 );
@background-color-backdrop-dark: rgba( 0, 0, 0, 0.65 );
@background-color-transparent: rgba( 255, 255, 255, 0 );
@background-color-neutral: #eaecf0;
@background-color-neutral-subtle: #f8f9fa;
@background-color-target-text: #fda;
@background-color-button-quiet--hover: rgba( 0, 24, 73, 0.027 );
@background-color-button-quiet--active: rgba( 0, 24, 73, 0.082 );
@background-color-input-binary--checked: #0645ad;
@background-color-tab-list-item-framed--hover: rgba( 255, 255, 255, 0.3 );
@background-color-tab-list-item-framed--active: rgba( 255, 255, 255, 0.65 );
@background-color-option-red: #ffe9e5;
@background-color-option-orange: #ffead4;
@background-color-option-yellow: #fdf2d5;
@background-color-option-lime: #e3f2e4;
@background-color-option-green: #dff2eb;
@background-color-option-blue: #e8eeff;
@background-color-option-purple: #f0ecf6;
@background-color-option-pink: #f5ebf2;
@background-color-option-maroon: #f6ebeb;
@color-base: #222;
@color-base-fixed: #222;
@color-base--hover: #444;
@color-emphasized: #000;
@color-neutral: #404244;
@color-subtle: #555;
@color-placeholder: #767676;
@color-disabled: #767676;
@color-inverted: #fff;
@color-inverted-fixed: #fff;
@color-progressive: #0645ad;
@color-progressive--hover: #447ff5;
@color-progressive--active: #2a4b8d;
@color-progressive--focus: #0645ad;
@color-destructive: #d03;
@color-destructive--hover: #ff4242;
@color-destructive--active: #b32424;
@color-destructive--focus: #d03;
@color-destructive--visited: #6b4ba1;
@color-destructive--visited--hover: #534fa3;
@color-destructive--visited--active: #353262;
@color-visited: #6b4ba1;
@color-visited--hover: #534fa3;
@color-visited--active: #353262;
@color-error: #d03;
@color-error--hover: #9f3526;
@color-error--active: #612419;
@color-warning: #edab00;
@color-success: #14866d;
@color-notice: #222;
@color-link: #0645ad;
@color-link--hover: #447ff5;
@color-link--active: #2a4b8d;
@color-link--focus: #0645ad;
@color-link--visited: #6b4ba1;
@color-link--visited--hover: #534fa3;
@color-link--visited--active: #353262;
@color-link-red: #d03;
@color-link-red--hover: #ff4242;
@color-link-red--active: #b32424;
@color-link-red--focus: #d03;
@color-link-red--visited: #a55858;
@color-link-red--visited--hover: #854848;
@color-link-red--visited--active: #512e2e;
@color-content-added: #096450;
@color-content-removed: #b32424;
@color-icon-error: #f54739;
@color-icon-warning: #ab7f2a;
@color-icon-success: #099979;
@color-icon-notice: #72777d;
@color-icon-progressive: #0645ad;
@color-disabled-emphasized: #a2a9b1;
@color-option-red: #bf3c2c;
@color-option-orange: #a95226;
@color-option-yellow: #886425;
@color-option-lime: #1f7a39;
@color-option-green: #177860;
@color-option-blue: #36c;
@color-option-purple: #6a60b0;
@color-option-pink: #9b527f;
@color-option-maroon: #9f5555;
@opacity-base: 1;
@opacity-medium: 0.67;
@opacity-low: 0.33;
@opacity-transparent: 0;
@filter-invert-icon: 0;
@filter-invert-primary-button-icon: 1;
@opacity-icon-base: 0.87;
@opacity-icon-base--hover: 0.74;
@opacity-icon-base--selected: 1;
@opacity-icon-base--disabled: 0.51;
@opacity-icon-placeholder: 0.51;
@opacity-icon-subtle: 0.67;
@background-position-base: center;
@z-index-bottom: -100; // Use descriptive `z-index` tokens for layout purposes.
@z-index-base: 0;
@z-index-above-content: 1;
@z-index-toolbar: 2;
@z-index-dropdown: 50;
@z-index-sticky: 100;
@z-index-fixed: 200;
@z-index-off-canvas-backdrop: 300;
@z-index-off-canvas: 350;
@z-index-overlay-backdrop: 400;
@z-index-overlay: 450;
@z-index-popover: 700;
@z-index-tooltip: 800;
@z-index-toast-notification: 900;
@z-index-top: 9999;
@z-index-stacking-0: 0; // Use stacking-specific z-index tokens inside components to layer individual elements.
@z-index-stacking-1: 1;
